#include "fleet/FleetIntentSystem.h"
namespace subspace {
std::vector<FleetIntentAssignment> FleetIntentSystem::Mirror(const std::vector<FleetWingShip>&w,StrategicOrderKind o) const {std::vector<FleetIntentAssignment>a;int count=0;for(const auto&s:w){if(!s.operational||s.role==FleetShipRole::Leader)continue;if(++count>4)break;FleetIntentAssignment x;x.shipId=s.id;x.order=o;switch(o){case StrategicOrderKind::Mine:if(s.role==FleetShipRole::Mining)x.behavior="Mine selected cluster";else if(s.role==FleetShipRole::Support)x.behavior="Support mining wing";else{x.order=StrategicOrderKind::Follow;x.behavior="Escort mining formation";}break;case StrategicOrderKind::Salvage:if(s.role==FleetShipRole::Salvage)x.behavior="Salvage selected wreck";else{x.order=StrategicOrderKind::Follow;x.behavior="Secure salvage operation";}break;case StrategicOrderKind::Engage:if(s.role==FleetShipRole::Support)x.behavior="Repair/support combat flight";else x.behavior="Engage leader target";break;case StrategicOrderKind::Dock:x.behavior="Queue dock / hold if berth unavailable";break;case StrategicOrderKind::VectorTo:x.behavior="Align and enter leader slipstream";break;default:x.behavior="Maintain formation and mirror movement";break;}a.push_back(x);}return a;}
FormationType FleetIntentSystem::FormationFor(const FleetFlightConfig&c,StrategicOrderKind o) const {if(!c.autoFormation)return c.travelFormation;if(o==StrategicOrderKind::Engage)return c.combatFormation;if(o==StrategicOrderKind::Mine||o==StrategicOrderKind::Salvage)return c.miningFormation;if(o==StrategicOrderKind::Dock)return FormationType::Column;return c.travelFormation;}
} // namespace subspace
